Read file /home/runner/work/PlayGround/PlayGround/game.js, lines 1-47
1: const cities={RUH:{name:'Riyadh',country:'Saudi Arabia',emoji:'🇸🇦'},DXB:{name:'Dubai',country:'UAE',emoji:'🇦🇪'},LHR:{name:'London',country:'United Kingdom',emoji:'🇬🇧'},JFK:{name:'New York',country:'United States',emoji:'🇺🇸'},HND:{name:'Tokyo',country:'Japan',emoji:'🇯🇵'},CDG:{name:'Paris',country:'France',emoji:'🇫🇷'},IST:{name:'Istanbul',country:'Türkiye',emoji:'🇹🇷'},CPT:{name:'Cape Town',country:'South Africa',emoji:'🇿🇦'},SYD:{name:'Sydney',country:'Australia',emoji:'🇦🇺'},DEL:{name:'Delhi',country:'India',emoji:'🇮🇳'}};
2: const rates={SAR:1,USD:3.75,EUR:4.05,GBP:4.75,AED:1.02,INR:.045};
3: const fares={Standard:0,'First class':30,'Business class':100};
4: const plans={Week:12,Month:39,Year:100};
5: const stages=['Home','Taxi','Check-in','Security','Gate','In flight','Landing'];
6: const defaults={stage:0,coins:500,origin:'RUH',destination:'DXB',flightClass:'Standard',pass:'No pass',admin:false,adminName:'Aviator',bagDone:false,flightRound:0,stars:0,house:0};
7: let state={...defaults,...JSON.parse(localStorage.getItem('cloudbound-save')||'{}')};
8: let currency='SAR',chosenClass='First class',chosenPlan='Week',flightTarget=1;
9: const game=document.getElementById('game');
10: function save(){localStorage.setItem('cloudbound-save',JSON.stringify(state));}
11: function city(code){return cities[code]||cities.RUH}
12: function toast(msg){const old=document.querySelector('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),2300)}
13: function setStage(n){state.stage=n;save();render()}
14: function art(){const s=state.stage;let scene=s===0?'Home sweet home':s===1?'Your ride is here':s===2?'Check-in desk':s===3?'Security check':s===4?'Ready for take-off':s===5?'Above the clouds':'Touchdown!';let graphic=s<=1?'<div class="house"><i class="window"></i></div><div class="taxi-art">🚕</div>':s<=3?'<div class="airport-art">🛄</div>':s===4?'<div class="airport-art">🛫</div><div class="boarding-plane">✈️</div>':s===5?'<div class="boarding-plane">✈️</div><div class="cloud c2"></div>':'<div class="airport-art">🛬</div>';return `<div class="scene-art"><div class="sun"></div><div class="cloud"></div><div class="cloud c2"></div><div class="hills back"></div><div class="hills"></div>${graphic}<span class="art-label">${scene}</span></div>`}
15: function routeCard(){return `<div class="route-card"><div class="route-line"><div><div class="airport-code">${state.origin}</div><div class="route-city">${city(state.origin).name}</div></div><div><div class="route-connector"></div></div><div style="text-align:right"><div class="airport-code">${state.destination}</div><div class="route-city">${city(state.destination).name}</div></div></div><div class="flight-meta"><span>✈ CB ${String(218+state.stage*7).padStart(3,'0')}</span><span>${state.flightClass}</span><span>✦ ${state.stars} stars</span></div></div><div class="ticket-mini"><div><small>Landing on your ticket</small><b>${city(state.destination).emoji} ${city(state.destination).name}</b></div><span class="ticket-class">${state.pass}</span></div>`}
16: function progress(){return `<div class="progress">${stages.map((s,i)=>`<div class="progress-step ${i===state.stage?'active':i<state.stage?'done':''}"><span class="number">${i<state.stage?'✓':i+1}</span><span>${s}</span></div>${i<stages.length-1?'<span class="progress-line"></span>':''}`).join('')}</div>`}
17: function panel(){let title='',copy='',button='',tag='YOUR JOURNEY';switch(state.stage){case 0:title='A little adventure awaits.';copy='Pick a destination, spend a few game coins on your home, then call a taxi. Your landing city is printed on your ticket from the very start.';button=`<button class="primary" onclick="beginTrip()">Plan my trip <span>→</span></button>`;tag='START AT HOME';break;case 1:title='Taxi to the terminal';copy='Your bags are ready. The airport taxi costs 35 game coins — no real-world money needed to get going.';button=`<button class="primary" onclick="rideTaxi()">Order airport taxi · 35 coins</button>`;tag='PICK-UP';break;case 2:title='Pack light, fly happy.';copy='Check your bag at the counter. Keep it under 20 kg and your carry-on close by.';button=`<button class="primary" onclick="openBag()">Check my luggage →</button>`;tag='BAG DROP';break;case 3:title='A quick security check';copy='Select the item that needs to go in the security tray. Keep your small luggage with you.';button=`<button class="primary" onclick="openSecurity()">I’m ready for security →</button>`;tag='SECURITY';break;case 4:title='Your gate is calling.';copy=`Ticket in hand? Head to the boarding place and scan your pass. Destination is ${city(state.destination).name}.`;button=`<button class="primary" onclick="openTicket()">View ticket & board →</button>`;tag='BOARDING';break;case 5:title='Pilot the friendly skies.';copy=`Choose a flight lane each turn. Dodge the clouds, collect sky stars, and guide your plane to ${city(state.destination).name}.`;button=`<div class="flight-controls"><div class="event-banner" id="flight-event">Pick a lane for this stretch of sky.</div><div class="lane-buttons"><button class="lane-btn" onclick="fly('left')">← Left</button><button class="lane-btn" onclick="fly('center')">↑ Center</button><button class="lane-btn" onclick="fly('right')">Right →</button></div><span class="hint">Flight ${state.flightRound}/5 · Stars collected: ${state.stars}</span></d... (line truncated to 2000 chars)
18: function side(){return `<aside class="side-card"><h3 class="side-title">Your trip <span class="eyebrow">✦ LIVE TICKET</span></h3>${routeCard()}<div class="side-bottom"><p class="hint">${state.admin?'Admin flight mode · all cabins & passes unlocked.':'Your destination is set before departure, and will stay printed on your ticket.'}</p>${state.stage===0?`<div class="actions"><button class="secondary full" onclick="openHouse()">⌂ ${state.house?'Upgrade':'Decorate'} your house · game coins</button></div>`:''}<div class="actions"><button class="text-button" onclick="openShop()">View cabins & fun passes →</button></div></div></aside>`}
19: function render(){document.getElementById('coin-count').textContent=state.coins;game.innerHTML=`<div class="welcome-row"><div><span class="eyebrow">${state.admin?'ADMIN FLIGHT DECK':'YOUR SKY, YOUR STORY'}</span><h1>Good ${new Date().getHours()<12?'morning':'day'}, ${state.admin?state.adminName:'Aviator'} <span style="color:var(--coral)">✦</span></h1><p>${state.stage===0?'Where shall we take off to today?':`On your way to ${city(state.destination).name} · ${city(state.destination).country}`}</p></div><span class="step-pill">${state.stage===6?'✦ Trip complete':`Journey ${state.stage+1} of 7`}</span></div>${progress()}<div class="content-grid">${panel()}${side()}</div>`;}
20: function beginTrip(){const origin=document.getElementById('origin-select').value,dest=document.getElementById('dest-select').value;if(origin===dest){toast('Choose two different cities.');return}state.origin=origin;state.destination=dest;save();openShop(true)}
21: function rideTaxi(){if(!state.admin&&state.coins<35){toast('Not enough game coins. Decorate your house later, or enjoy the starter coins!');return}if(!state.admin)state.coins-=35;setStage(2);toast('Taxi arrived at the airport!')}
22: function openBag(){modal(`<div class="modal-head"><div><span class="eyebrow">BAG DROP</span><h2>Check your luggage</h2></div><button class="close" onclick="closeModal()">×</button></div><p>Choose your checked bag weight. Your carry-on stays with you.</p><div class="field"><label>SUITCASE WEIGHT · LIMIT 20 KG</label><input id="bag-weight" type="range" min="5" max="28" value="14" oninput="document.getElementById('weight-value').textContent=this.value+' kg'"></div><div class="event-banner">Suitcase: <b id="weight-value">14 kg</b> &nbsp; · &nbsp; Carry-on: 4 kg</div><div class="modal-actions"><button class="primary" onclick="bagConfirm()">Drop my bag →</button></div><p class="inline-note" id="bag-note"></p>`)}
23: function bagConfirm(){const w=+document.getElementById('bag-weight').value;if(w>20){document.getElementById('bag-note').textContent='That bag is a little heavy — slide it under 20 kg.';return}closeModal();state.bagDone=true;setStage(3);toast(`${w} kg checked. Small bag stays with you!`)}
24: function openSecurity(){modal(`<div class="modal-head"><div><span class="eyebrow">SECURITY</span><h2>What goes in the tray?</h2></div><button class="close" onclick="closeModal()">×</button></div><p>Tap the water bottle to place it in the tray. Your small luggage and other things can come through with you.</p><div class="item-grid"><button class="bag-item" onclick="this.classList.toggle('marked')"><span>💧</span>Water bottle</button><button class="bag-item" onclick="this.classList.toggle('marked')"><span>💻</span>Laptop</button><button class="bag-item" onclick="this.classList.toggle('marked')"><span>🧸</span>Teddy bear</button></div><div class="modal-actions"><button class="primary" onclick="securityDone()">Continue through security →</button></div><p class="inline-note" id="security-note"></p>`)}
25: function securityDone(){const items=[...document.querySelectorAll('.bag-item')],water=items.find(e=>e.textContent.includes('Water bottle'));if(!water?.classList.contains('marked')){document.getElementById('security-note').textContent='The water bottle needs to go in the tray. Tap it and try again.';return}closeModal();setStage(4);toast('Security complete — have a lovely flight!')}
26: function openHouse(){modal(`<div class="modal-head"><div><span class="eyebrow">HOME SWEET HOME</span><h2>Make your house lovely</h2></div><button class="close" onclick="closeModal()">×</button></div><p>Decorate your house using game coins earned on your journeys. This never uses real money.</p><div class="price-grid">${[['Cozy porch',100,'🌿'],['Sunny garden',175,'🌻'],['Dreamy rooftop',250,'🌙']].map((x,i)=>`<button class="price-option" onclick="buyHouse(${x[1]},'${x[0]}')"><b>${x[2]} ${x[0]}</b><span class="price">${x[1]} coins</span><small>${state.house>i?'Already added':'Decor upgrade'}</small></button>`).join('')}</div><p class="inline-note" id="house-note"></p><button class="secondary full" onclick="closeModal()">Back to my trip</button>`)}
27: function buyHouse(cost,name){if(state.coins<cost){document.getElementById('house-note').textContent='You need a few more game coins. Complete a flight to earn more!';return}state.coins-=cost;state.house++;save();render();openHouse();toast(`${name} added to your home!`)}
28: function openAdmin(){modal(`<div class="modal-head"><div><span class="eyebrow">FLIGHT DECK ACCESS</span><h2>${state.admin?'Admin flight deck':'Hello, captain'}</h2></div><button class="close" onclick="closeModal()">×</button></div>${state.admin?`<div class="admin-panel">Admin mode is active. All cabin fares and fun passes are free, and you can choose any origin and landing city from the world destination list.</div><div class="field"><label>ADMIN DISPLAY NAME</label><input id="admin-name" value="${state.adminName}"></div><div class="modal-actions"><button class="secondary" onclick="state.admin=false;save();closeModal();render()">Leave admin mode</button><button class="primary" onclick="state.adminName=document.getElementById('admin-name').value||'Captain';save();closeModal();render()">Save</button></div>`:`<p>Enter your administrator code to unlock free cabins and passes for this demo.</p><div class="field"><label>ADMIN CODE</label><input id="admin-code" type="password" placeholder="Enter code" autocomplete="off"></div><p class="notice">Demo administrator code: <b>SKY777</b></p><p class="inline-note" id="admin-note"></p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="checkAdmin()">Unlock flight deck</button></div>`}`)}
29: function checkAdmin(){const input=document.getElementById('admin-code').value;if(input!=='SKY777'){document.getElementById('admin-note').textContent='That code didn’t work. Try the demo code shown above.';return}state.admin=true;state.flightClass='First class';state.pass='Admin pass';save();closeModal();render();toast('Welcome, admin — all extras are free!')}
30: function openProfile(){modal(`<div class="modal-head"><div><span class="eyebrow">YOUR PILOT CARD</span><h2>Aviator profile</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="admin-panel">${state.coins} game coins · ${state.stars} sky stars · ${state.house} home upgrades</div><p>Progress saves on this device. All game coins are pretend and have no cash value.</p><button class="secondary full" onclick="closeModal()">Back to my trip</button>`)}
31: function newTrip(){state.coins+=80+state.stars*15;state.origin=state.destination;state.destination=Object.keys(cities).find(c=>c!==state.origin)||'LHR';state.flightRound=0;state.stars=0;state.flightClass=state.admin?'First class':'Standard';state.stage=0;save();render();toast('Arrival bonus added to your game wallet!')}
32: let skyChallenge={cloud:0,star:2};const lanes=['left','center','right'];function nextSky(){const cloud=Math.floor(Math.random()*3);let star=Math.floor(Math.random()*3);while(star===cloud)star=Math.floor(Math.random()*3);skyChallenge={cloud,star};}
33: function fly(lane){const laneIndex=lanes.indexOf(lane);let message;if(laneIndex===skyChallenge.cloud){message='A fluffy cloud! You dodged the bump — no star this time.'}else if(laneIndex===skyChallenge.star){state.stars++;state.coins+=8;message='Beautiful flying! You collected a sky star and 8 game coins.'}else{message='Smooth skies — keep your course.'}state.flightRound++;if(state.flightRound>=5){state.coins+=80+state.stars*15;state.stage=6;save();render();toast(`Landed in ${city(state.destination).name}! Arrival bonus added.`);return}nextSky();save();render();document.getElementById('flight-event').textContent=`${message} Next: cloud in ${lanes[skyChallenge.cloud]}, star in ${lanes[skyChallenge.star]}.`}
34: const renderBase=render;render=function(){renderBase();if(state.stage===5){document.getElementById('flight-event').textContent=`Cloud in ${lanes[skyChallenge.cloud]} · Sky star in ${lanes[skyChallenge.star]} — choose your lane!`}};
