*{box-sizing:border-box} :root{color-scheme:dark;--bg:#17151f;--panel:#211f2b;--panel2:#292634;--ink:#f7f3e9;--muted:#a19daa;--line:#393644;--lime:#d8ff56;--pink:#ff7296;--purple:#a993ff;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}html{min-height:100%;background:var(--bg)}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% -25%,#373041 0,transparent 58%),var(--bg);color:var(--ink);font-family:var(--sans);overflow-x:hidden}.noise{position:fixed;inset:0;pointer-events:none;opacity:.13;z-index:5;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.17'/%3E%3C/svg%3E")}.topbar{height:74px;padding:0 clamp(20px,5vw,76px);display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff13;position:relative;z-index:2}.brand{font-weight:700;font-size:19px;letter-spacing:-.8px;color:var(--ink);text-decoration:none;display:flex;align-items:center;gap:8px}.brand-icon{height:25px;width:25px;display:grid;place-items:center;border-radius:8px;background:var(--lime);color:#17151f;font-weight:700;font-size:17px;transform:rotate(-7deg)}.brand-period{color:var(--lime);margin-left:-8px}.header-right{display:flex;align-items:center;gap:25px}.best-label,.footer{font:500 10px var(--mono);letter-spacing:1.15px;color:var(--muted)}.best-label b{color:var(--lime);font-size:13px;margin-left:8px}.sound-toggle{border:1px solid var(--line);border-radius:20px;background:transparent;color:var(--ink);padding:8px 11px;font-size:12px;cursor:pointer}.sound-toggle span{font:10px var(--mono);color:var(--muted);margin-left:4px}.app{max-width:1120px;min-height:calc(100vh - 128px);margin:auto;padding:35px 32px 38px;display:flex;align-items:center;justify-content:center}.footer{height:54px;padding:0 clamp(20px,5vw,76px);border-top:1px solid #ffffff13;display:flex;align-items:center;justify-content:space-between;font-size:9px}.hero{width:100%;display:grid;grid-template-columns:1.05fr .95fr;gap:7%;align-items:center}.kicker{font:500 11px var(--mono);letter-spacing:1.7px;color:var(--lime);text-transform:uppercase;display:flex;align-items:center;gap:9px}.kicker:before{content:'';width:23px;height:1px;background:var(--lime)}h1,h2,p{margin-top:0}.hero h1{font-size:clamp(54px,8vw,98px);letter-spacing:-.09em;line-height:.88;margin:22px 0 21px;font-weight:700;max-width:540px}.hero h1 em{font-style:normal;color:var(--lime);display:block}.hero-copy{font-size:17px;line-height:1.6;color:#b8b4bf;max-width:390px;margin:0 0 28px}.hero-copy strong{color:var(--ink);font-weight:600}.primary{border:0;background:var(--lime);color:#17151f;padding:15px 20px;border-radius:8px;font:700 15px var(--sans);letter-spacing:-.2px;box-shadow:0 5px 0 #91b624;transition:transform .15s,box-shadow .15s;cursor:pointer}.primary:hover{transform:translateY(-2px);box-shadow:0 7px 0 #91b624}.primary:active{transform:translateY(3px);box-shadow:0 1px 0 #91b624}.button-arrow{font-size:19px;margin-left:20px}.hero-foot{margin-top:20px;color:var(--muted);font:10px var(--mono);letter-spacing:.5px}.hero-foot span{color:var(--pink)}.poster{min-height:390px;position:relative;display:grid;place-items:center}.poster-ring{width:min(360px,35vw);aspect-ratio:1;border:1px solid #ffffff1c;border-radius:50%;position:absolute;transform:rotate(-18deg)}.poster-ring:before,.poster-ring:after{content:'';position:absolute;border:1px dashed #ffffff22;border-radius:50%;inset:20px}.poster-ring:after{inset:-19px 45px}.poster-card{z-index:1;width:min(330px,90%);min-height:280px;background:var(--lime);color:#1b1921;border-radius:14px;padding:24px;transform:rotate(5deg);box-shadow:14px 17px 0 #a993ff;display:flex;flex-direction:column;justify-content:space-between}.poster-card .mini-label{font:500 10px var(--mono);letter-spacing:1.1px}