const TOTAL=10,SECONDS=10;
const app=document.getElementById('app');
let best=Number(localStorage.getItem('all-wrong-best')||0),round=0,score=0,streak=0,bestStreak=0,deck=[],current=null,remaining=SECONDS,timer=null,locked=false,muted=true,audioCtx=null;
