const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function goHome(){stopTimer();renderHome()}
function renderHome(){app.innerHTML=`<section class="hero"><div><div class="kicker">THE TRIVIA GAME FOR CONTRARIANS</div><h1>All <em>wrong.</em></h1><p class="hero-copy">A trivia game where the right answer is <strong>the wrong answer.</strong> Ten questions. Three choices. Avoid the truth at all costs.</p><button class="primary" onclick="startGame()">I’m ready to be wrong <span class="button-arrow">↗</span></button><div class="hero-foot"><span>✦</span> 10 ROUNDS · 10 SECONDS EACH · ZERO PRESSURE TO BE RIGHT</div></div><div class="poster" aria-hidden="true"><div class="poster-ring"></div><span class="spark one">✳</span><span class="spark two">✦</span><div class="stamp">FACT CHECKED? NEVER.</div><div class="poster-card"><span class="mini-label">SAMPLE QUESTION 01 / 10</span><div class="sample-q">What do bees make?</div><div class="fake-answer">A tiny leather jacket <span>← YES!</span></div></div></div></section>`}
function startGame(){stopTimer();const all=questions.map((_,i)=>i);for(let i=all.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[all[i],all[j]]=[all[j],all[i]]}deck=all.slice(0,TOTAL);round=0;score=0;streak=0;bestStreak=0;nextQuestion()}
function nextQuestion(){if(round>=TOTAL){finishGame();return}current=questions[deck[round]];round++;remaining=SECONDS;locked=false;renderQuestion();startTimer()}
function renderQuestion(){const dots=Array.from({length:TOTAL},(_,i)=>`<span class="round-dot ${i<round-1?'done':i===round-1?'current':''}">${i<round-1?'✓':String(i+1).padStart(2,'0')}</span>`).join('');app.innerHTML=`<section class="game-wrap"><div class="game-top"><div class="round-label">ROUND <strong>${String(round).padStart(2,'0')}</strong> <span>/ ${TOTAL}</span></div><div class="streak-label">WRONG STREAK <strong>×${streak}</strong></div></div><div class="game-grid"><article class="question-card"><div class="question-category">${esc(current.category)}</div><h1 class="question">${esc(current.q)}</h1><div class="answer-list">${current.a.map((a,i)=>`<button class="answer" data-choice="${i}" onclick="choose(${i})"><span class="answer-key">${i+1}</span><span>${esc(a)}</span></button>`).join('')}</div><div class="answer-result" id="answer-result"><span>Pick an answer that is confidently incorrect.</span><span></span></div></article><aside class="side-stack"><div class="side-box"><div class="side-title">YOUR SCORE</div><div class="score-number" id="score-value">${score}<span> pts</span></div><div class="score-note">WRONG IS RIGHT HERE</div><div class="timer-wrap"><div class="timer-bar" id="timer-bar"></div></div><div class="timer-readout"><span>TIME TO BE WRONG</span><b id="time-value">10.0s</b></div></div><div class="side-box"><div class="side-title">THE TEN</div><div class="round-dots">${dots}</div></div><div class="side-box help-box"><p class="side-help"><b>One rule:</b> don’t pick the real answer. Wrong answers score points. The faster you do it, the more you get.</p></div></aside></div></section>`;document.getElementById('live-region').textContent=`Round ${round}: ${current.q}`}

