function startTimer(){stopTimer();const started=Date.now();timer=setInterval(()=>{if(locked)return;remaining=Math.max(0,SECONDS-(Date.now()-started)/1000);const bar=document.getElementById('timer-bar'),text=document.getElementById('time-value');if(bar){bar.style.width=`${remaining/SECONDS*100}%`;bar.classList.toggle('urgent',remaining<=3)}if(text)text.textContent=`${remaining.toFixed(1)}s`;if(remaining<=0){stopTimer();timeOut()}},50)}
function stopTimer(){if(timer){clearInterval(timer);timer=null}}
function choose(index){if(locked)return;locked=true;stopTimer();const buttons=[...document.querySelectorAll('.answer')],correct=index===current.correct;buttons.forEach((b,i)=>{b.disabled=true;if(i===current.correct)b.classList.add('correct-trap');if(i===index&&!correct)b.classList.add('wrong-win')});const feedback=document.getElementById('answer-result');if(correct){streak=0;feedback.innerHTML='<span>Oh no—you told the truth!</span><b>0 POINTS</b>';playTone(false);showPop('Too right!','That was the real answer. The truth is a point vacuum.','😬',()=>nextQuestion())}else{const points=100+Math.floor(remaining*20)+Math.min(streak,5)*25;score+=points;streak++;bestStreak=Math.max(bestStreak,streak);document.getElementById('score-value').innerHTML=`${score}<span> pts</span>`;document.querySelector('.streak-label strong').textContent=`×${streak}`;feedback.innerHTML=`<span>Beautifully, gloriously wrong.</span><b>+${points} POINTS</b>`;playTone(true);showPop('Wrong answer. Nailed it.',`+${points} points — the correct answer was “${current.a[current.correct]}”.`, '✦',()=>nextQuestion(),true)}}
